(3, 70881, 'tv', 'Boruto: Naruto Next Generations', '/e0B6i48kxdRkMcK4tR4YNfXGWOc.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/4jDRuUk02VGAVMBJXabI9r0Cj6j.jpg\",\"id\":70881,\"name\":\"Boruto: Naruto Next Generations\",\"original_name\":\"BORUTO-\\u30dc\\u30eb\\u30c8- NARUTO NEXT GENERATIONS\",\"overview\":\"The life of the shinobi is beginning to change. Boruto Uzumaki, son of Seventh Hokage Naruto Uzumaki, has enrolled in the Ninja Academy to learn the ways of the ninja. Now, as a series of mysterious events unfolds, Boruto\\u2019s story is about to begin!\",\"poster_path\":\"\\/e0B6i48kxdRkMcK4tR4YNfXGWOc.jpg\",\"media_type\":\"tv\",\"original_language\":\"ja\",\"genre_ids\":[16,10759,35],\"popularity\":20.2729,\"first_air_date\":\"2017-04-05\",\"softcore\":false,\"vote_average\":7.8,\"vote_count\":2526,\"origin_country\":[\"JP\"]}', '2026-10-01 05:08:43', '2026-10-01 05:08:43'),
(4, 46260, 'tv', 'Naruto', '/xppeysfvDKVx775MFuH8Z9BlpMk.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/5F0HVEgkgP99fEWDjPyikGt9jQi.jpg\",\"id\":46260,\"name\":\"Naruto\",\"original_name\":\"\\u30ca\\u30eb\\u30c8\",\"overview\":\"Naruto Uzumaki, a mischievous adolescent ninja, struggles as he searches for recognition and dreams of becoming the Hokage, the village\'s leader and strongest ninja.\",\"poster_path\":\"\\/xppeysfvDKVx775MFuH8Z9BlpMk.jpg\",\"media_type\":\"tv\",\"original_language\":\"ja\",\"genre_ids\":[16,10759,10765],\"popularity\":165.9465,\"first_air_date\":\"2002-10-03\",\"softcore\":false,\"vote_average\":8.363,\"vote_count\":6131,\"origin_country\":[\"JP\"]}', '2026-10-01 05:08:43', '2026-10-01 05:08:43'),
(5, 31910, 'tv', 'Naruto Shippūden', '/kV27j3Nz4d5z8u6mN3EJw9RiLg2.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/swFtS1S5556BFrQNJkwTTmyBFIT.jpg\",\"id\":31910,\"name\":\"Naruto Shipp\\u016bden\",\"original_name\":\"\\u30ca\\u30eb\\u30c8 \\u75be\\u98a8\\u4f1d\",\"overview\":\"After 2 and a half years Naruto finally returns to his village of Konoha, and sets about putting his ambitions to work. It will not be easy though as he has amassed a few more dangerous enemies, in the likes of the shinobi organization; Akatsuki.\",\"poster_path\":\"\\/kV27j3Nz4d5z8u6mN3EJw9RiLg2.jpg\",\"media_type\":\"tv\",\"original_language\":\"ja\",\"genre_ids\":[16,10759,10765],\"popularity\":120.8234,\"first_air_date\":\"2007-02-15\",\"softcore\":false,\"vote_average\":8.5,\"vote_count\":8795,\"origin_country\":[\"JP\"]}', '2026-10-01 05:08:43', '2026-10-01 05:08:43'),
(6, 317442, 'movie', 'The Last: Naruto the Movie', '/bAQ8O5Uw6FedtlCbJTutenzPVKd.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/l8ubUlfzlB5R2j9cJ3CN7tj0gmd.jpg\",\"id\":317442,\"title\":\"The Last: Naruto the Movie\",\"original_title\":\"THE LAST -NARUTO THE MOVIE-\",\"overview\":\"Two years after the events of the Fourth Great Ninja War, the moon that Hagoromo Otsutsuki created long ago to seal away the Gedo Statue begins to descend towards the world, threatening to become a meteor that would destroy everything on impact. Amidst this crisis, a direct descendant of Kaguya Otsutsuki named Toneri Otsutsuki attempts to kidnap Hinata Hyuga but ends up abducting her younger sister Hanabi. Naruto and his allies now mount a rescue mission before finding themselves embroiled in a final battle to decide the fate of everything.\",\"poster_path\":\"\\/bAQ8O5Uw6FedtlCbJTutenzPVKd.jpg\",\"media_type\":\"movie\",\"original_language\":\"ja\",\"genre_ids\":[28,10749,16],\"popularity\":10.2465,\"release_date\":\"2014-12-06\",\"softcore\":false,\"video\":false,\"vote_average\":7.5,\"vote_count\":2426}', '2026-10-01 05:08:43', '2026-10-01 05:08:43'),
(7, 16907, 'movie', 'Naruto the Movie: Ninja Clash in the Land of Snow', '/eUNRUeSNzm8LktH4HRaYiAReB6R.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/bW0Hr19Xo7LDnMmywXuH5YoTMY5.jpg\",\"id\":16907,\"title\":\"Naruto the Movie: Ninja Clash in the Land of Snow\",\"original_title\":\"\\u5287\\u5834\\u7248 NARUTO \\u5927\\u6d3b\\u5287! \\u96ea\\u59eb\\u5fcd\\u6cd5\\u5e16\\u3060\\u3063\\u3066\\u3070\\u3088!!\",\"overview\":\"Naruto is thrilled when he is sent on a mission to protect his favorite actress, Yukie Fujikaze, on the set of her new movie, The Adventures of Princess Gale. But when the crew ventures out to film in the icy, foreboding Land of Snow, Yukie mysteriously flees! Naruto and his squad set off to find her... unaware that three Snow Ninja lie in wait, with a sinister purpose that will force Yukie to face her hidden past!\",\"poster_path\":\"\\/eUNRUeSNzm8LktH4HRaYiAReB6R.jpg\",\"media_type\":\"movie\",\"original_language\":\"ja\",\"genre_ids\":[35,28,16,12],\"popularity\":6.7199,\"release_date\":\"2004-08-21\",\"softcore\":false,\"video\":false,\"vote_average\":7.3,\"vote_count\":633}', '2026-10-01 05:08:43', '2026-10-01 05:08:43'),
(8, 17581, 'movie', 'Naruto Shippuden the Movie: Bonds', '/bBqEiQbbfyt4MWR3NhDZMbS4Wp8.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/5lDGto4oxjoWDt2bMFgT3rhJZ0n.jpg\",\"id\":17581,\"title\":\"Naruto Shippuden the Movie: Bonds\",\"original_title\":\"\\u5287\\u5834\\u7248 NARUTO -\\u30ca\\u30eb\\u30c8- \\u75be\\u98a8\\u4f1d \\u7d46\",\"overview\":\"A mysterious group of ninjas makes a surprise attack on the Konohagakure, which takes great damage. The nightmare of another Shinobi World War could become a reality. Sasuke, who was still a missing nin from Konoha trying to kill his brother, Itachi, appears for the second time in front of Naruto at an unknown location to prevent it from happening.\",\"poster_path\":\"\\/bBqEiQbbfyt4MWR3NhDZMbS4Wp8.jpg\",\"media_type\":\"movie\",\"original_language\":\"ja\",\"genre_ids\":[14,16,28],\"popularity\":5.9175,\"release_date\":\"2008-08-02\",\"softcore\":false,\"video\":false,\"vote_average\":7.3,\"vote_count\":534}', '2026-10-01 05:08:43', '2026-10-01 05:08:43'),
(9, 118406, 'movie', 'Road to Ninja: Naruto the Movie', '/xLal6fXNtiJN6Zw6qk21xAtdOeN.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/hBIZ6RiaCWszRbdvHAy6RWHyT3c.jpg\",\"id\":118406,\"title\":\"Road to Ninja: Naruto the Movie\",\"original_title\":\"ROAD TO NINJA -NARUTO THE MOVIE-\",\"overview\":\"Sixteen years ago, a mysterious masked ninja unleashes a powerful creature known as the Nine-Tailed Demon Fox on the Hidden Leaf Village Konoha, killing many people. In response, the Fourth Hokage Minato Namikaze and his wife Kushina Uzumaki, the Demon Fox\'s living prison or Jinch\\u016briki, manage to seal the creature inside their newborn son Naruto Uzumaki. With the Tailed Beast sealed, things continued as normal. However, in the present day, peace ended when a group of ninja called the Akatsuki attack Konoha under the guidance of Tobi, the mysterious masked man behind Fox\'s rampage years ago who intends on executing his plan to rule the world by shrouding it in illusions.\",\"poster_path\":\"\\/xLal6fXNtiJN6Zw6qk21xAtdOeN.jpg\",\"media_type\":\"movie\",\"original_language\":\"ja\",\"genre_ids\":[16,14,28],\"popularity\":8.7321,\"release_date\":\"2012-07-28\",\"softcore\":false,\"video\":false,\"vote_average\":7.4,\"vote_count\":1261}', '2026-10-01 05:08:43', '2026-10-01 05:08:43'),
(10, 36728, 'movie', 'Naruto Shippuden the Movie: The Will of Fire', '/pZzdFmztwmg0FUOVCMa7vReHhQN.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/jeT8bG6PiGWFqvjiR0Pd83xag9e.jpg\",\"id\":36728,\"title\":\"Naruto Shippuden the Movie: The Will of Fire\",\"original_title\":\"\\u5287\\u5834\\u7248 NARUTO -\\u30ca\\u30eb\\u30c8- \\u75be\\u98a8\\u4f1d \\u706b\\u306e\\u610f\\u5fd7\\u3092\\u7d99\\u3050\\u8005\",\"overview\":\"Ninjas with bloodline limits begin disappearing in all the countries and blame points toward the fire nation. By Tsunade\'s order, Kakashi is sacrificed to prevent an all out war. After inheriting charms left by Kakashi, Naruto fights through friends and foes to prevent his death while changing the minds of those who\'ve inherited the will of fire.\",\"poster_path\":\"\\/pZzdFmztwmg0FUOVCMa7vReHhQN.jpg\",\"media_type\":\"movie\",\"original_language\":\"ja\",\"genre_ids\":[28,12,35,18,14,16],\"popularity\":6.6721,\"release_date\":\"2009-08-01\",\"softcore\":false,\"video\":false,\"vote_average\":7.4,\"vote_count\":521}', '2026-10-01 05:08:43', '2026-10-01 05:08:43'),
(11, 75624, 'movie', 'Naruto Shippuden the Movie: Blood Prison', '/4WT7zYFpe0fsbg6TitppiHddWAh.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/yFPzrBaRqmX7yWs5xFCZFVgQReI.jpg\",\"id\":75624,\"title\":\"Naruto Shippuden the Movie: Blood Prison\",\"original_title\":\"\\u5287\\u5834\\u7248 NARUTO -\\u30ca\\u30eb\\u30c8- \\u30d6\\u30e9\\u30c3\\u30c9\\u30fb\\u30d7\\u30ea\\u30ba\\u30f3\",\"overview\":\"After his capture for attempted assassination of the Raikage, leader of Kumogakure, as well as killing J\\u014dnin from Kirigakure and Iwagakure, Naruto is imprisoned in H\\u014dzukijou: A criminal containment facility known as the Blood Prison. Mui, the castle master, uses the ultimate imprisonment technique to steal power from the prisoners, which is when Naruto notices his life has been targeted. Thus begins the battle to uncover the truth behind the mysterious murders and prove Naruto\'s innocence.\",\"poster_path\":\"\\/4WT7zYFpe0fsbg6TitppiHddWAh.jpg\",\"media_type\":\"movie\",\"original_language\":\"ja\",\"genre_ids\":[53,16,28,35,27,9648],\"popularity\":7.0938,\"release_date\":\"2011-07-30\",\"softcore\":false,\"video\":false,\"vote_average\":7.2,\"vote_count\":714}', '2026-10-01 05:08:43', '2026-10-01 05:08:43'),
(12, 75219, 'tv', '9-1-1', '/6njUqsd3By2mJsdZm1P0moPLzs3.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/h050XJoiIobaH6bhj3MAhgilkpJ.jpg\",\"id\":75219,\"name\":\"9-1-1\",\"original_name\":\"9-1-1\",\"overview\":\"Explore the high-pressure experiences of police officers, paramedics and firefighters who are thrust into the most frightening, shocking and heart-stopping situations. These emergency responders must try to balance saving those who are at their most vulnerable with solving the problems in their own lives.\",\"poster_path\":\"\\/6njUqsd3By2mJsdZm1P0moPLzs3.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[18,80,10759],\"popularity\":144.9359,\"first_air_date\":\"2018-01-03\",\"softcore\":false,\"vote_average\":8.218,\"vote_count\":2862,\"origin_country\":[\"US\"]}', '2026-10-01 05:09:33', '2026-10-01 05:09:33'),
(13, 30801, 'tv', '2 Days and 1 Night', '/qezeCEkIKHQM5iwyVeYBuXmYA2h.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/32iRX9xqNH3ErJN6FowxdtgYmiY.jpg\",\"id\":30801,\"name\":\"2 Days and 1 Night\",\"original_name\":\"1\\ubc15 2\\uc77c\",\"overview\":\"2 Days & 1 Night is a South Korean reality-variety show with the motto \\\"real wild road variety.\\\" Its main concept is to recommend various places of interest that viewers can visit in South Korea.\",\"poster_path\":\"\\/qezeCEkIKHQM5iwyVeYBuXmYA2h.jpg\",\"media_type\":\"tv\",\"original_language\":\"ko\",\"genre_ids\":[35,10764],\"popularity\":209.4526,\"first_air_date\":\"2007-08-05\",\"softcore\":false,\"vote_average\":6.7,\"vote_count\":30,\"origin_country\":[\"KR\"]}', '2026-10-01 05:09:33', '2026-10-01 05:09:33'),
(14, 1673393, 'movie', 'Krishnavataram Part 1: The Heart (Hridayam)', '/7AxJYvPWLlNiGH52A9eenDxQzu8.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/quMadsmJAFKGd6UpCFwxtlrVxPF.jpg\",\"id\":1673393,\"title\":\"Krishnavataram Part 1: The Heart (Hridayam)\",\"original_title\":\"\\u0915\\u0943\\u0937\\u094d\\u0923\\u093e\\u0935\\u0924\\u0930\\u092e \\u092d\\u093e\\u0917 1: \\u0939\\u0943\\u0926\\u092f (\\u0939\\u0943\\u0926\\u092f\\u092e\\u094d)\",\"overview\":\"An epic devotional narrative that reimagines the journey of Lord Krishna, tracing his path from Dwarka to Kurukshetra after parting ways with Radha. As his journey unfolds, it explores his connection with people, his layered personality, and the lessons he imparts about love and life.\",\"poster_path\":\"\\/7AxJYvPWLlNiGH52A9eenDxQzu8.jpg\",\"media_type\":\"movie\",\"original_language\":\"hi\",\"genre_ids\":[12,10749,18],\"popularity\":3.0896,\"release_date\":\"2026-05-07\",\"softcore\":false,\"video\":false,\"vote_average\":8.9,\"vote_count\":7}', '2026-10-01 05:09:33', '2026-10-01 05:09:33'),
(15, 4629, 'tv', 'Stargate SG-1', '/dQjmI7XxI47v8IM2MUysHG0LuU2.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/yOyzlRw54oYaGvhUBdPr7TFwtrX.jpg\",\"id\":4629,\"name\":\"Stargate SG-1\",\"original_name\":\"Stargate SG-1\",\"overview\":\"The story of Stargate SG-1 begins about a year after the events of the feature film, when the United States government learns that an ancient alien device called the Stargate can access a network of such devices on a multitude of planets. SG-1 is an elite Air Force special operations team, one of more than two dozen teams from Earth who explore the galaxy and defend against alien threats such as the Goa\'uld, Replicators, and the Ori.\",\"poster_path\":\"\\/dQjmI7XxI47v8IM2MUysHG0LuU2.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[10765,10759],\"popularity\":135.7748,\"first_air_date\":\"1997-07-27\",\"softcore\":false,\"vote_average\":8.266,\"vote_count\":1907,\"origin_country\":[\"US\",\"CA\"]}', '2026-10-01 05:09:33', '2026-10-01 05:09:33'),
(16, 259140, 'tv', 'Ranma1/2', '/cDThx8yRYbdPOSgHbjihS4q7GYc.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/xvD9urN8lUtWw5fm4a87Rl3dCZn.jpg\",\"id\":259140,\"name\":\"Ranma1\\/2\",\"original_name\":\"\\u3089\\u3093\\u307e1\\/2\",\"overview\":\"Akane Tendo meets her new fianc\\u00e9, Ranma Saotome, a martial arts prodigy with a twist: he magically transforms into a girl upon touching cold water.\",\"poster_path\":\"\\/cDThx8yRYbdPOSgHbjihS4q7GYc.jpg\",\"media_type\":\"tv\",\"original_language\":\"ja\",\"genre_ids\":[16,10759,35],\"popularity\":110.1481,\"first_air_date\":\"2024-10-06\",\"softcore\":false,\"vote_average\":8.052,\"vote_count\":184,\"origin_country\":[\"JP\"]}', '2026-10-01 05:09:33', '2026-10-01 05:09:33'),
(17, 269, 'tv', 'One Tree Hill', '/sOrelBaAhp7DZbPTivDwKEyPslC.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/gJOpHgHa37qnglH3dL9g63iztky.jpg\",\"id\":269,\"name\":\"One Tree Hill\",\"original_name\":\"One Tree Hill\",\"overview\":\"In Tree Hill, North Carolina two half brothers share a last name and nothing else. Brooding, blue-collar Lucas is a talented street-side basketball player, but his skills are appreciated only by his friends at the river court. Popular, affluent Nathan basks in the hero-worship of the town, as the star of his high school team. And both boys are the son of former college ball player Dan Scott whose long ago choice to abandon Lucas and his mother Karen, will haunt him long into his life with wife Deb and their son Nathan.\",\"poster_path\":\"\\/sOrelBaAhp7DZbPTivDwKEyPslC.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[18],\"popularity\":119.2974,\"first_air_date\":\"2003-09-23\",\"softcore\":false,\"vote_average\":7.8,\"vote_count\":631,\"origin_country\":[\"US\"]}', '2026-10-01 05:09:33', '2026-10-01 05:09:33'),
(18, 40610, 'tv', 'Polizeiinspektion 1', '/5RbxVNsEfKkHDWKVZlJXxRkx58x.jpg', '{\"adult\":false,\"backdrop_path\":null,\"id\":40610,\"name\":\"Polizeiinspektion 1\",\"original_name\":\"Polizeiinspektion 1\",\"overview\":\"Polizeiinspektion 1 is a German television series.\",\"poster_path\":\"\\/5RbxVNsEfKkHDWKVZlJXxRkx58x.jpg\",\"media_type\":\"tv\",\"original_language\":\"de\",\"genre_ids\":[80],\"popularity\":20.1405,\"first_air_date\":\"1977-09-01\",\"softcore\":false,\"vote_average\":10,\"vote_count\":1,\"origin_country\":[\"DE\"]}', '2026-10-01 05:09:33', '2026-10-01 05:09:33'),
(19, 431, 'tv', 'One on One', '/wrPeock4PW1VV2bw8k1TuGet8hX.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/htCFjaC5w7NY3wnMTPuPMsoM5WH.jpg\",\"id\":431,\"name\":\"One on One\",\"original_name\":\"One on One\",\"overview\":\"A sportscaster becomes a full-time dad when his ex-wife decides to accept a job out of the country and his teenage daughter, Breanna, moves in with him.\",\"poster_path\":\"\\/wrPeock4PW1VV2bw8k1TuGet8hX.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[35,10767],\"popularity\":33.9607,\"first_air_date\":\"2001-09-03\",\"softcore\":false,\"vote_average\":7.9,\"vote_count\":39,\"origin_country\":[\"US\"]}', '2026-10-01 05:09:33', '2026-10-01 05:09:33'),
(20, 1607127, 'movie', 'One Last Shot', '/niQ4NBh2jqAf1hDZP5m6ReWFAb7.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/8giIQcHpxgsPVP6c7aQtHl3txuh.jpg\",\"id\":1607127,\"title\":\"One Last Shot\",\"original_title\":\"One Last Shot\",\"overview\":\"Navy Seal Jake Harris must stop a team of mercenaries, led by his disillusioned former comrade, from disabling the US missile defense network.\",\"poster_path\":\"\\/niQ4NBh2jqAf1hDZP5m6ReWFAb7.jpg\",\"media_type\":\"movie\",\"original_language\":\"en\",\"genre_ids\":[28,53],\"popularity\":125.3148,\"release_date\":\"2026-09-22\",\"softcore\":false,\"video\":false,\"vote_average\":7.406,\"vote_count\":80}', '2026-10-01 05:09:33', '2026-10-01 05:09:33'),
(21, 111110, 'tv', 'ONE PIECE', '/blWCPEqDGLBuLB9u89CxP9ORQP4.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/qD211Hb5XwFxrszzBBe5EUYJerh.jpg\",\"id\":111110,\"name\":\"ONE PIECE\",\"original_name\":\"ONE PIECE\",\"overview\":\"With his straw hat and ragtag crew, young pirate Monkey D. Luffy goes on an epic voyage for treasure.\",\"poster_path\":\"\\/blWCPEqDGLBuLB9u89CxP9ORQP4.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[10759,10765],\"popularity\":37.8961,\"first_air_date\":\"2023-08-31\",\"softcore\":false,\"vote_average\":8.112,\"vote_count\":1950,\"origin_country\":[\"US\"]}', '2026-10-01 05:09:33', '2026-10-01 05:09:33'),
(22, 1368337, 'movie', 'The Odyssey', '/5rhTDKUhPYvpdQIijFIs5VoWsON.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/bulFtfy3oBQtCnAMSi7g6DSSds3.jpg\",\"id\":1368337,\"title\":\"The Odyssey\",\"original_title\":\"The Odyssey\",\"overview\":\"Odysseus, the legendary King of Ithaca, embarks on a long and perilous journey home following the Trojan War. Throughout his voyage, he is forced to confront the whims of gods, mythological monsters, and trials that stretch both his cunning and his humanity to the breaking point.\",\"poster_path\":\"\\/5rhTDKUhPYvpdQIijFIs5VoWsON.jpg\",\"media_type\":\"movie\",\"original_language\":\"en\",\"genre_ids\":[12,28,14],\"popularity\":314.6106,\"release_date\":\"2026-07-15\",\"softcore\":false,\"video\":false,\"vote_average\":8.013,\"vote_count\":3982}', '2026-10-01 05:09:57', '2026-10-01 05:09:57');
INSERT INTO `media` (`id`, `tmdb_id`, `media_type`, `title`, `poster_path`, `data`, `created_at`, `updated_at`) VALUES
(23, 1698863, 'movie', 'The Odyssey', '/b0z3ViIC5AkbJoqxmTpqyjgmoJs.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/mPy1xSASQ9NYWJdAGx2C2sOsnNw.jpg\",\"id\":1698863,\"title\":\"The Odyssey\",\"original_title\":\"The Odyssey\",\"overview\":\"Based on the Ancient Greek epic. After ten years of war, King Odysseus sets sail for Ithaca, eager to reunite with his beloved. But his journey home is far more treacherous than the battlefield, as he must face deadly monsters and vengeful gods to survive.\",\"poster_path\":\"\\/b0z3ViIC5AkbJoqxmTpqyjgmoJs.jpg\",\"media_type\":\"movie\",\"original_language\":\"en\",\"genre_ids\":[12,14,28],\"popularity\":26.0361,\"release_date\":\"2026-07-03\",\"softcore\":false,\"video\":false,\"vote_average\":4.054,\"vote_count\":638}', '2026-10-01 05:09:57', '2026-10-01 05:09:57'),
(24, 9687, 'tv', 'The Odyssey', '/wCiQ7XySqnz9X1REtDNZRGLfhpe.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/wVRd4VjrkJ4WObvfjqUZhlmN3gT.jpg\",\"id\":9687,\"name\":\"The Odyssey\",\"original_name\":\"The Odyssey\",\"overview\":\"Warrior Odysseus leaves his idyllic life in the kingdom of Ithaca to fight in the Trojan War. Following victory, he now must endure a lengthy, decade-long return journey, and with all his wits, overcome deadly monsters, powerful forces of nature, seductive enchantresses, and even journey into the bowels of the Underworld.\",\"poster_path\":\"\\/wCiQ7XySqnz9X1REtDNZRGLfhpe.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[10759,10765,18],\"popularity\":13.9446,\"first_air_date\":\"1997-05-18\",\"softcore\":false,\"vote_average\":7.287,\"vote_count\":893,\"origin_country\":[\"US\",\"GB\"]}', '2026-10-01 05:09:58', '2026-10-01 05:09:58'),
(25, 113094, 'movie', 'Ultraman Tiga: The Final Odyssey', '/papDk5x8wmkamSpEm70Ssc6SqQG.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/e2Mkm8eK9IyRSwaDCg6eaeQnr9M.jpg\",\"id\":113094,\"title\":\"Ultraman Tiga: The Final Odyssey\",\"original_title\":\"\\u30a6\\u30eb\\u30c8\\u30e9\\u30de\\u30f3\\u30c6\\u30a3\\u30ac THE FINAL ODYSSEY\",\"overview\":\"Ultraman Tiga: The Final Oddysey was sort of an epilogue of the Ultraman Tiga series. Just when we thought that the world is safe, it\'s under attack again! A TPC excursion (including GUTS\' Captain Megumi Iruma) headed to an old ruins and unintentionally woke up three evil ancient giants whom Daigo, later on, has visions of. What\'s so haunting about his visions is that they\'re not only three but four evil giants, including Ultraman Tiga in a very dark physique and a very evil aura. After a series of visions, Daigo was able to meet the three evils who beat him up and left the Black Spark Lens to him. Later on, the ultimate battle begins in the ancient ruins. Daigo as Ultraman Tiga, who is supposed to be the warrior of light, must use his powers, however dark, in order to defeat the three evils.\",\"poster_path\":\"\\/papDk5x8wmkamSpEm70Ssc6SqQG.jpg\",\"media_type\":\"movie\",\"original_language\":\"ja\",\"genre_ids\":[28,12,10751,14,878],\"popularity\":2.5083,\"release_date\":\"2000-03-08\",\"softcore\":false,\"video\":false,\"vote_average\":6.8,\"vote_count\":27}', '2026-10-01 05:09:58', '2026-10-01 05:09:58'),
(26, 11121, 'tv', 'The Odyssey', '/ixeOYFcCj6YjKrliC13pxGFNTK2.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/2m4MtdIuOr7G1ZCWw9GXDghnmzv.jpg\",\"id\":11121,\"name\":\"The Odyssey\",\"original_name\":\"The Odyssey\",\"overview\":\"The Odyssey is a Canadian-produced half-hour adventure-fantasy television series for children, originally broadcast 1992-94 on CBC Television. It starred Illya Woloshyn as Jay Ziegler, Ashleigh Aston Moore as Donna\\/Alpha, Tony Sampson as Keith\\/Flash, Andrea Nemeth as Medea\\/Sierra Jones, Mark Hildreth as Finger, Ryan Reynolds as Macro, Janet Hodgkinson as Val Ziegler, and Devon Sawa as Yudo.\",\"poster_path\":\"\\/ixeOYFcCj6YjKrliC13pxGFNTK2.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[10751,10765],\"popularity\":10.1887,\"first_air_date\":\"1992-03-09\",\"softcore\":false,\"vote_average\":7.2,\"vote_count\":16,\"origin_country\":[\"CA\"]}', '2026-10-01 05:09:58', '2026-10-01 05:09:58'),
(27, 19401, 'tv', 'The Odyssey', '/4iBgeghJz97TjQK9CUPyD8kz8K3.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/ndbch3UDR1tdxkJ9PVBBbh1sZHe.jpg\",\"id\":19401,\"name\":\"The Odyssey\",\"original_name\":\"Odissea\",\"overview\":\"Odysseus\' journey, told in Homer\'s Iliad and Odyssey. After fighting in the Trojan War, Odysseus spends years trying to return home to Itaka.\",\"poster_path\":\"\\/4iBgeghJz97TjQK9CUPyD8kz8K3.jpg\",\"media_type\":\"tv\",\"original_language\":\"it\",\"genre_ids\":[18,10759,10765,10768],\"popularity\":9.4809,\"first_air_date\":\"1968-03-24\",\"softcore\":false,\"vote_average\":8.4,\"vote_count\":21,\"origin_country\":[\"IT\"]}', '2026-10-01 05:09:59', '2026-10-01 05:09:59'),
(28, 49338, 'tv', 'The Jacques Cousteau Odyssey', '/f9h3d6W6VBMxpKv9STGMLy9QU2x.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/89JveOkoRosmdSSu9ocJw4RnBr2.jpg\",\"id\":49338,\"name\":\"The Jacques Cousteau Odyssey\",\"original_name\":\"The Jacques Cousteau Odyssey\",\"overview\":\"The Jacques Cousteau Odyssey includes all 12 episodes of the 1978 television series featuring the research adventures of Cousteau, a celebrated documentarian and public conscience of mankind\'s stewardship of our oceans. Alongside his son Philippe Cousteau, Jacques\'s adventures begin with an ambitious expedition (on Cousteau\'s famous Calypso ship and a seaplane called the Catalina) following the course of the Nile River from Central Africa to the Mediterranean.\",\"poster_path\":\"\\/f9h3d6W6VBMxpKv9STGMLy9QU2x.jpg\",\"media_type\":\"tv\",\"original_language\":\"fr\",\"genre_ids\":[99],\"popularity\":2.2659,\"first_air_date\":\"1979-12-09\",\"softcore\":false,\"vote_average\":8.4,\"vote_count\":9,\"origin_country\":[\"US\"]}', '2026-10-01 05:09:59', '2026-10-01 05:09:59'),
(29, 45571, 'tv', 'The Story of Film: An Odyssey', '/g0TCWFNIFHO8u2yy1hboUDIhD6n.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/5ZV8kYvo5LfFmTtNGI3wJ2W6lGC.jpg\",\"id\":45571,\"name\":\"The Story of Film: An Odyssey\",\"original_name\":\"The Story of Film: An Odyssey\",\"overview\":\"A worldwide guided tour of the greatest movies ever made and the story of international cinema through the history of cinematic innovation.\",\"poster_path\":\"\\/g0TCWFNIFHO8u2yy1hboUDIhD6n.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[99],\"popularity\":10.3031,\"first_air_date\":\"2011-09-03\",\"softcore\":false,\"vote_average\":7.7,\"vote_count\":69,\"origin_country\":[\"GB\"]}', '2026-10-01 05:09:59', '2026-10-01 05:09:59'),
(30, 86991, 'movie', '2012 The Odyssey', '/bkU09zpaxmJGr34jIPo1cZPxjfa.jpg', '{\"adult\":false,\"backdrop_path\":null,\"id\":86991,\"title\":\"2012 The Odyssey\",\"original_title\":\"2012 The Odyssey\",\"overview\":\"The Mayan Calendar is ending on December 21st 2012. What will happen to us between now and then? Are there other prophecies that also predict the closing of this world age and the start of a new beginning?  Join author Sharron Rose on an adventure into the future. In this exciting and thought provoking feature documentary she travels across the entire United States speaking to the many experts on this fast approaching prophecy. They help her to reveal the secrets that will unfold before our eyes and will shape our future.\",\"poster_path\":\"\\/bkU09zpaxmJGr34jIPo1cZPxjfa.jpg\",\"media_type\":\"movie\",\"original_language\":\"en\",\"genre_ids\":[99],\"popularity\":0.7002,\"release_date\":\"2007-08-01\",\"softcore\":false,\"video\":false,\"vote_average\":6,\"vote_count\":4}', '2026-10-01 05:10:12', '2026-10-01 05:10:12'),
(31, 126775, 'tv', 'Straight to Video: The B-Movie Odyssey', '/yksKoBTQC2o4Fj5ZP0ALKQIHO6k.jpg', '{\"adult\":false,\"backdrop_path\":null,\"id\":126775,\"name\":\"Straight to Video: The B-Movie Odyssey\",\"original_name\":\"Straight to Video: The B-Movie Odyssey\",\"overview\":\"Kevin a video store clerk is closing his store, when he accidentally opens a vortex and gets sucked in with some of his movies. He has to fight his way through different genres to stay alive.\",\"poster_path\":\"\\/yksKoBTQC2o4Fj5ZP0ALKQIHO6k.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[10759,35,10765,9648],\"popularity\":1.8963,\"first_air_date\":\"2015-03-17\",\"softcore\":false,\"vote_average\":7,\"vote_count\":2,\"origin_country\":[\"CA\"]}', '2026-10-01 05:10:12', '2026-10-01 05:10:12'),
(32, 60802, 'tv', 'The Last Ship', '/xH529hDtPxhslAEeCrN7gD64ZMX.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/yTUwiQLbr8gHDs8LuU28c8fBQFm.jpg\",\"id\":60802,\"name\":\"The Last Ship\",\"original_name\":\"The Last Ship\",\"overview\":\"Their mission is simple: Find a cure. Stop the virus. Save the world. When a global pandemic wipes out eighty percent of the planet\'s population, the crew of a lone naval destroyer must find a way to pull humanity from the brink of extinction.\",\"poster_path\":\"\\/xH529hDtPxhslAEeCrN7gD64ZMX.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[10759,18,10765],\"popularity\":61.1253,\"first_air_date\":\"2014-06-22\",\"softcore\":false,\"vote_average\":6.9,\"vote_count\":1087,\"origin_country\":[\"US\"]}', '2026-10-01 05:17:48', '2026-10-01 05:17:48'),
(33, 1641580, 'movie', 'The Last Assassins', '/dCEvwyR3XlTos78iHZzPa8a3urg.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/gRh0ZzVpjVW03AnOQNsO5aSYN9b.jpg\",\"id\":1641580,\"title\":\"The Last Assassins\",\"original_title\":\"The Last Assassins\",\"overview\":\"After her father is murdered, a young warrior known as \\u201cThe Kid\\u201d and her guardian cross a violent dystopian future in search of the aunt she has never met. The world is trapped in permanent winter and shrouded in deadly fog, and Nobel is bound by an oath to protect the few remaining members of her family. Their journey leads them to an abandoned laboratory, where holograms reveal secrets from the family\\u2019s past. But as the boundary between the digital and physical worlds begins to collapse, the young woman may hold the key to what comes next.\",\"poster_path\":\"\\/dCEvwyR3XlTos78iHZzPa8a3urg.jpg\",\"media_type\":\"movie\",\"original_language\":\"en\",\"genre_ids\":[878,12,53,28],\"popularity\":32.1674,\"release_date\":\"2026-07-21\",\"softcore\":false,\"video\":false,\"vote_average\":6,\"vote_count\":6}', '2026-10-01 05:17:48', '2026-10-01 05:17:48'),
(34, 1516698, 'movie', 'The Last Sunrise', '/3PWJqDfygN0YNNjWsDUOXclCp3h.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/zFCWfU2ViMIm38G1W8UsnSpqmWn.jpg\",\"id\":1516698,\"title\":\"The Last Sunrise\",\"original_title\":\"The Last Sunrise\",\"overview\":\"Ry, a college student with a chronic illness, escapes to Mallorca for the summer with her mother, where she unexpectedly falls for a local and begins to embrace living in the moment. But as her condition worsens and long-hidden family secrets come to light, everything she has found before summer\'s end is threatened.\",\"poster_path\":\"\\/3PWJqDfygN0YNNjWsDUOXclCp3h.jpg\",\"media_type\":\"movie\",\"original_language\":\"en\",\"genre_ids\":[10749,18],\"popularity\":59.4803,\"release_date\":\"2026-08-26\",\"softcore\":false,\"video\":false,\"vote_average\":6.858,\"vote_count\":204}', '2026-10-01 05:17:48', '2026-10-01 05:17:48'),
(35, 63333, 'tv', 'The Last Kingdom', '/8eJf0hxgIhE6QSxbtuNCekTddy1.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/QbtctI8EzlhsyFDMUMyG3fli8B.jpg\",\"id\":63333,\"name\":\"The Last Kingdom\",\"original_name\":\"The Last Kingdom\",\"overview\":\"A show of heroic deeds and epic battles with a thematic depth that embraces politics, religion, warfare, courage, love, loyalty and our universal search for identity. Combining real historical figures and events with fictional characters, it is the story of how a people combined their strength under one of the most iconic kings of history in order to reclaim their land for themselves and build a place they call home.\",\"poster_path\":\"\\/8eJf0hxgIhE6QSxbtuNCekTddy1.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[10759,18,10768],\"popularity\":49.3034,\"first_air_date\":\"2015-10-10\",\"softcore\":false,\"vote_average\":8.257,\"vote_count\":2051,\"origin_country\":[\"GB\"]}', '2026-10-01 05:17:48', '2026-10-01 05:17:48'),
(36, 82452, 'tv', 'Avatar: The Last Airbender', '/lzZpWEaqzP0qVA5nkCc5ASbNcSy.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/aVvRQJ2Ckhlym4uh0YGc166CUoP.jpg\",\"id\":82452,\"name\":\"Avatar: The Last Airbender\",\"original_name\":\"Avatar: The Last Airbender\",\"overview\":\"A young boy known as the Avatar must master the four elemental powers to save a world at war \\u2014 and fight a ruthless enemy bent on stopping him.\",\"poster_path\":\"\\/lzZpWEaqzP0qVA5nkCc5ASbNcSy.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[10759,10765,18,10751],\"popularity\":75.0491,\"first_air_date\":\"2024-02-22\",\"softcore\":false,\"vote_average\":7.773,\"vote_count\":1373,\"origin_country\":[\"US\"]}', '2026-10-01 05:17:48', '2026-10-01 05:17:48'),
(37, 100088, 'tv', 'The Last of Us', '/dmo6TYuuJgaYinXBPjrgG9mB5od.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/lY2DhbA7Hy44fAKddr06UrXWWaQ.jpg\",\"id\":100088,\"name\":\"The Last of Us\",\"original_name\":\"The Last of Us\",\"overview\":\"Twenty years after modern civilization has been destroyed, Joel, a hardened survivor, is hired to smuggle Ellie, a 14-year-old girl, out of an oppressive quarantine zone. What starts as a small job soon becomes a brutal, heartbreaking journey, as they both must traverse the United States and depend on each other for survival.\",\"poster_path\":\"\\/dmo6TYuuJgaYinXBPjrgG9mB5od.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[18],\"popularity\":57.8242,\"first_air_date\":\"2023-01-15\",\"softcore\":false,\"vote_average\":8.405,\"vote_count\":7376,\"origin_country\":[\"US\"]}', '2026-10-01 05:17:48', '2026-10-01 05:17:48'),
(38, 63706, 'tv', 'The Last Leg', '/4euDsPzadRhz0m5CZhQlKcgbZGI.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/23AlZs7Teu9Gl4b4EEIQlh0Inb5.jpg\",\"id\":63706,\"name\":\"The Last Leg\",\"original_name\":\"The Last Leg\",\"overview\":\"Adam Hills and co-hosts Josh Widdicombe and Alex Brooker provide some offbeat commentary on the significant moments of the past seven days.\",\"poster_path\":\"\\/4euDsPzadRhz0m5CZhQlKcgbZGI.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[10767],\"popularity\":48.1125,\"first_air_date\":\"2013-01-25\",\"softcore\":false,\"vote_average\":5.7,\"vote_count\":26,\"origin_country\":[\"GB\"]}', '2026-10-01 05:17:48', '2026-10-01 05:17:48'),
(39, 1318467, 'movie', 'The Last Kiss', '/cLZ7iFZc25vluSIKt3XtdSTait4.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/ifAdNCn67jW5y7hcDOUozjRBLU0.jpg\",\"id\":1318467,\"title\":\"The Last Kiss\",\"original_title\":\"The Last Kiss\",\"overview\":\"Laurel always imagined her first kiss would be a fairy tale. Instead, that fantasy turns frightening when she\'s cursed with an ability to see the death of anyone she kisses. After a vision reveals her crush is doomed to die in a strange murder spree targeting her closest friends, she races to unmask the killer before the mystery becomes a massacre.\",\"poster_path\":\"\\/cLZ7iFZc25vluSIKt3XtdSTait4.jpg\",\"media_type\":\"movie\",\"original_language\":\"en\",\"genre_ids\":[27,9648,53],\"popularity\":22.7781,\"release_date\":\"2026-09-15\",\"softcore\":false,\"video\":false,\"vote_average\":6.3,\"vote_count\":19}', '2026-10-01 05:17:48', '2026-10-01 05:17:48'),
(40, 246, 'tv', 'Avatar: The Last Airbender', '/yaGt4GIutpbXHsv48tWceWg6s56.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/7oBGhqJIghRBvOwo5Qe0yM0cnMc.jpg\",\"id\":246,\"name\":\"Avatar: The Last Airbender\",\"original_name\":\"Avatar: The Last Airbender\",\"overview\":\"In a war-torn world of elemental magic, a young boy reawakens to undertake a dangerous mystic quest to fulfill his destiny as the Avatar, and bring peace to the world.\",\"poster_path\":\"\\/yaGt4GIutpbXHsv48tWceWg6s56.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[16,10759,10765],\"popularity\":40.2957,\"first_air_date\":\"2005-02-21\",\"softcore\":false,\"vote_average\":8.781,\"vote_count\":5124,\"origin_country\":[\"US\"]}', '2026-10-01 05:17:48', '2026-10-01 05:17:48'),
(41, 221079, 'tv', 'The Last Frontier', '/4S2gS1mECZ5wDRBVAZE6KWmJHI3.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/pzxIAuKHqQqCFOxh2ALmHUgXkOD.jpg\",\"id\":221079,\"name\":\"The Last Frontier\",\"original_name\":\"The Last Frontier\",\"overview\":\"When a prison transport plane crashes in the remote Alaskan wilderness\\u2014freeing dozens of violent inmates\\u2014the region\'s lone marshal must protect the town he\'s vowed to keep safe.\",\"poster_path\":\"\\/4S2gS1mECZ5wDRBVAZE6KWmJHI3.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[18,80],\"popularity\":18.2545,\"first_air_date\":\"2025-10-09\",\"softcore\":false,\"vote_average\":7.2,\"vote_count\":234,\"origin_country\":[\"US\"]}', '2026-10-01 05:17:48', '2026-10-01 05:17:48');
