(47, 462103, 'movie', 'Who was Hitler', '/3IvtUU65Xzuw3StE7VjxDAfWGZc.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/Wde6vVUinCJBJ4XrHFAN419bca.jpg\",\"id\":462103,\"title\":\"Who was Hitler\",\"original_title\":\"Wer war Hitler\",\"overview\":\"Hitler\'s biography told like never before. Besides brief historical localizations by a narrator, only contemporaries and Hitler himself speak: no interviews, no reenactment, no illustrative graphics and no technical gadgets. The testimonies from diaries, letters, speeches and autobiographies are assembled with new, often unpublished archive material. Hitler\'s life and work are thus reflected in a unique way in interaction with the image of the society in the years 1889 to 1945.\",\"poster_path\":\"\\/3IvtUU65Xzuw3StE7VjxDAfWGZc.jpg\",\"media_type\":\"movie\",\"original_language\":\"de\",\"genre_ids\":[99,36],\"popularity\":1.5957,\"release_date\":\"2017-11-16\",\"softcore\":false,\"video\":false,\"vote_average\":5.7,\"vote_count\":3}', '2026-10-01 05:19:05', '2026-10-01 05:19:05'),
(48, 318379, 'tv', 'Wer gewinnt?', '/vMR9XMldrG1SUa90nfD12uDfYsL.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/mLL9nwJOJx8cu13gvJlQXjUsP7C.jpg\",\"id\":318379,\"name\":\"Wer gewinnt?\",\"original_name\":\"Wer gewinnt?\",\"overview\":\"Brian brings new contestants into the game \\u2013 and the challenges become even tougher, more absurd, and more unpredictable. Who will go the distance? Who will lose all inhibitions? In every episode, big personalities, wild strategies, and sheer madness collide \\u2013 and the tasks might take the contestants all across Germany or even beyond. Anything can happen! Whether it\\u2019s strategy, luck, or pure determination \\u2013 in the end, only one question matters: Who wins?\",\"poster_path\":\"\\/vMR9XMldrG1SUa90nfD12uDfYsL.jpg\",\"media_type\":\"tv\",\"original_language\":\"de\",\"genre_ids\":[10759,10764],\"popularity\":2.8235,\"first_air_date\":\"2025-06-25\",\"softcore\":false,\"vote_average\":0,\"vote_count\":0,\"origin_country\":[\"DE\"]}', '2026-10-01 05:19:05', '2026-10-01 05:19:05'),
(49, 795803, 'movie', 'Who We Were', '/o18WujwpHeS237L0zOxK3BKgDLa.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/eMMYNG8bs0LwPp1GZY715V2jqFG.jpg\",\"id\":795803,\"title\":\"Who We Were\",\"original_title\":\"Wer wir waren\",\"overview\":\"A look at the current state of the world, from the hand of six intellectuals and scientists who reflect on the present and postulate about the future.\",\"poster_path\":\"\\/o18WujwpHeS237L0zOxK3BKgDLa.jpg\",\"media_type\":\"movie\",\"original_language\":\"de\",\"genre_ids\":[99],\"popularity\":1.0015,\"release_date\":\"2021-07-08\",\"softcore\":false,\"video\":false,\"vote_average\":6.6,\"vote_count\":8}', '2026-10-01 05:19:05', '2026-10-01 05:19:05'),
