(58, 21210, 'tv', 'Gaiking: Legend of Daiku-Maryu', '/oVSYxdFjxH4vE8ZmBMYChk4hHO.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/7LTohh7iHQNjVvySr0jASMOJMnP.jpg\",\"id\":21210,\"name\":\"Gaiking: Legend of Daiku-Maryu\",\"original_name\":\"\\u30ac\\u30a4\\u30ad\\u30f3\\u30b0 LEGEND OF DAIKU-MARYU\",\"overview\":\"Gaiking: Legend of Daikuu-Maryuu is a Super Robot mecha anime series produced by Toei Animation. It was a reimagining of the original series created by Go Nagai, and was aired in TV Asahi from November 12, 2005 to September 24, 2006, lasting a total of 39 episodes. It originally replaced Bobobo-bo Bo-bobo in its timeslot.\",\"poster_path\":\"\\/oVSYxdFjxH4vE8ZmBMYChk4hHO.jpg\",\"media_type\":\"tv\",\"original_language\":\"ja\",\"genre_ids\":[16],\"popularity\":15.3671,\"first_air_date\":\"2005-11-12\",\"softcore\":false,\"vote_average\":5.5,\"vote_count\":4,\"origin_country\":[\"JP\"]}', '2026-10-01 05:20:10', '2026-10-01 05:20:10'),
(59, 726684, 'movie', 'Miraculous World: Shanghai - The Legend of Ladydragon', '/ouUf9zIq8PzGROyWunyEhubfFMS.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/rlNnwObbMu5G2FaOUlacnUIdIIA.jpg\",\"id\":726684,\"title\":\"Miraculous World: Shanghai - The Legend of Ladydragon\",\"original_title\":\"Miraculous World : Shanghai, la l\\u00e9gende de Ladydragon\",\"overview\":\"On school break, Marinette heads to Shanghai to meet Adrien. But after arriving, Marinette loses all her stuff, including the Miraculous that allows her to turn into Ladybug!\",\"poster_path\":\"\\/ouUf9zIq8PzGROyWunyEhubfFMS.jpg\",\"media_type\":\"movie\",\"original_language\":\"fr\",\"genre_ids\":[16,10751,28,12,14],\"popularity\":8.582,\"release_date\":\"2021-05-15\",\"softcore\":false,\"video\":false,\"vote_average\":7.9,\"vote_count\":701}', '2026-10-01 05:20:10', '2026-10-01 05:20:10'),
(60, 33880, 'tv', 'The Legend of Korra', '/dZgYvSfuh1YHDrJuILlVQ5oA2hF.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/bauKfP3CX5JPAXpmveOlPG1pngC.jpg\",\"id\":33880,\"name\":\"The Legend of Korra\",\"original_name\":\"The Legend of Korra\",\"overview\":\"Avatar Korra, a headstrong, rebellious, feisty young woman who continually challenges and breaks with tradition, is on her quest to become a fully realized Avatar. In this story, the Avatar struggles to find balance within herself.\",\"poster_path\":\"\\/dZgYvSfuh1YHDrJuILlVQ5oA2hF.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[16,10759,10765],\"popularity\":55.9026,\"first_air_date\":\"2012-04-14\",\"softcore\":false,\"vote_average\":8.222,\"vote_count\":2435,\"origin_country\":[\"US\"]}', '2026-10-01 05:20:10', '2026-10-01 05:20:10'),
(61, 128237, 'tv', 'Legend of Mana -The Teardrop Crystal-', '/7ls6XvZQqrGgbaJRw6ulsJVzfi3.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/87WbN1Ia1L4p75gkOuwbOlU5MsB.jpg\",\"id\":128237,\"name\":\"Legend of Mana -The Teardrop Crystal-\",\"original_name\":\"\\u8056\\u5263\\u4f1d\\u8aac Legend of Mana -The Teardrop Crystal-\",\"overview\":\"Not far from the town of Domina lives Shiloh, a boy who keeps hearing a voice in his dreams about a mission he must fulfill. But what mission could he be needed for remains unknown. That all changes when he meets two Jumi, a race that\\u2019s hunted for their unique gemstones, as a sudden outbreak of attacks against the Jumi occurs. His dream, his quest, becomes clear\\u2014help the Jumi and their gemstones!\",\"poster_path\":\"\\/7ls6XvZQqrGgbaJRw6ulsJVzfi3.jpg\",\"media_type\":\"tv\",\"original_language\":\"ja\",\"genre_ids\":[16,10759,10765],\"popularity\":7.8874,\"first_air_date\":\"2022-10-08\",\"softcore\":false,\"vote_average\":4.7,\"vote_count\":9,\"origin_country\":[\"JP\"]}', '2026-10-01 05:20:10', '2026-10-01 05:20:10'),
(62, 62643, 'tv', 'DC\'s Legends of Tomorrow', '/qNgAcg4gNYbZ9mySLB9ZX4ehZb6.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/be8fOACxsVyaX6lZLlQOWNqF0g2.jpg\",\"id\":62643,\"name\":\"DC\'s Legends of Tomorrow\",\"original_name\":\"DC\'s Legends of Tomorrow\",\"overview\":\"When heroes alone are not enough ... the world needs legends. Having seen the future, one he will desperately try to prevent from happening, time-traveling rogue Rip Hunter is tasked with assembling a disparate group of both heroes and villains to confront an unstoppable threat \\u2014 one in which not only is the planet at stake, but all of time itself. Can this ragtag team defeat an immortal threat unlike anything they have ever known?\",\"poster_path\":\"\\/qNgAcg4gNYbZ9mySLB9ZX4ehZb6.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[10759,10765,18],\"popularity\":90.9313,\"first_air_date\":\"2016-01-21\",\"softcore\":false,\"vote_average\":7.24,\"vote_count\":2523,\"origin_country\":[\"US\"]}', '2026-10-01 05:20:10', '2026-10-01 05:20:10');
