(65, 108978, 'tv', 'Reacher', '/f1VCQIG2iCyOookdgOzwtUpwWC0.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/pF0qkRsrHkdYadPWY9AMeFZfcwk.jpg\",\"created_by\":[{\"id\":78417,\"credit_id\":\"5f54f833713ed40036eed3e7\",\"name\":\"Nick Santora\",\"original_name\":\"Nick Santora\",\"gender\":2,\"profile_path\":\"\\/iipP9fTQhRuPJHFMhbpMCceBiiu.jpg\"}],\"episode_run_time\":[],\"first_air_date\":\"2022-02-03\",\"genres\":[{\"id\":10759,\"name\":\"Action & Adventure\"},{\"id\":80,\"name\":\"Crime\"}],\"homepage\":\"https:\\/\\/www.amazon.com\\/dp\\/B09ML1ZF3D\",\"id\":108978,\"in_production\":true,\"languages\":[\"en\"],\"last_air_date\":\"2026-09-16\",\"last_episode_to_air\":{\"id\":7438868,\"name\":\"Cut\",\"overview\":\"Reacher, Tamara and Jacob take the fight to the enemy as the full extent of their plot is revealed. Reacher faces off with those responsible for Anna\'s death while Jacob faces a moment of truth and Plum gets his shot at redemption.\",\"vote_average\":8.161,\"vote_count\":31,\"air_date\":\"2026-09-16\",\"episode_number\":8,\"episode_type\":\"finale\",\"production_code\":\"RCHR 408\",\"runtime\":56,\"season_number\":4,\"show_id\":108978,\"still_path\":\"\\/ws0BfBP2GMxW7F4yHMUnJyUirV6.jpg\"},\"name\":\"Reacher\",\"next_episode_to_air\":null,\"networks\":[{\"id\":1024,\"logo_path\":\"\\/w7HfLNm9CWwRmAMU58udl2L7We7.png\",\"name\":\"Prime Video\",\"origin_country\":\"\"}],\"number_of_episodes\":32,\"number_of_seasons\":4,\"origin_country\":[\"US\"],\"original_language\":\"en\",\"original_name\":\"Reacher\",\"overview\":\"Jack Reacher, a veteran military police investigator, has just recently entered civilian life. Reacher is a drifter, carrying no phone and the barest of essentials as he travels the country and explores the nation he once served.\",\"popularity\":603.2777,\"poster_path\":\"\\/f1VCQIG2iCyOookdgOzwtUpwWC0.jpg\",\"production_companies\":[{\"id\":20580,\"logo_path\":\"\\/oRR9EXVoKP9szDkVKlze5HVJS7g.png\",\"name\":\"Amazon Studios\",\"origin_country\"