(72, 14874, 'movie', 'Try Seventeen', '/oXgmh24wIlKLAlvVnZ4gZnYsrkh.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/AqRYUwWbHpbP8PK2q8magXOlOI8.jpg\",\"id\":14874,\"title\":\"Try Seventeen\",\"original_title\":\"Try Seventeen\",\"overview\":\"Teenager Jones has opted not to go to college and is instead renting a room in a boarding house to work on his writing skills. Soon, Jones finds himself dividing his time between two women: a young actress named Lisa and a photographer named Jane. After Jane\'s ex-boyfriend arrives to help her recover from a car accident, Jones begins to understand just how much he cares for her.\",\"poster_path\":\"\\/oXgmh24wIlKLAlvVnZ4gZnYsrkh.jpg\",\"media_type\":\"movie\",\"original_language\":\"en\",\"genre_ids\":[35,10749,18],\"popularity\":2.6444,\"release_date\":\"2002-09-10\",\"softcore\":false,\"video\":false,\"vote_average\":6.2,\"vote_count\":123}', '2026-10-01 07:42:38', '2026-10-01 07:42:38'),
