(75, 283648, 'tv', 'Try? Choo-ry!', '/nNGN4rrwCjBnan0AW4MOY0n1c14.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/kCcVPsRCgTUf3PC06kEdUawzQL5.jpg\",\"id\":283648,\"name\":\"Try? Choo-ry!\",\"original_name\":\"\\ucd94\\ub77c\\uc774 \\ucd94\\ub77c\\uc774\",\"overview\":\"MMA star Choo Sung-hoon leaves the cage behind to host a talk show. Get ready for candid conversations and fun challenges as he bonds with his guests.\",\"poster_path\":\"\\/nNGN4rrwCjBnan0AW4MOY0n1c14.jpg\",\"media_type\":\"tv\",\"original_language\":\"ko\",\"genre_ids\":[10767],\"popularity\":4.4649,\"first_air_date\":\"2025-02-26\",\"softcore\":false,\"vote_average\":10,\"vote_count\":1,\"origin_country\":[\"KR\"]}', '2026-10-01 07:42:38', '2026-10-01 07:42:38'),
(76, 1605793, 'movie', 'Try Again', '/5FkZBPx2EDsfrUt850zXA20mVT8.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/1yLJFtSPtnlSSCCaXRFfFZhWD45.jpg\",\"id\":1605793,\"title\":\"Try Again\",\"original_title\":\"Try Again\",\"overview\":\"What if you only had 24 chances to fall in love \\u2014 and every mistake reset the day?  Adithyaa, a socially awkward romantic, finally asks out his crush. But a divine error traps him in a time loop where the same date keeps repeating \\u2014 again and again.  Watched over by two exhausted celestial officials, Adithyaa tries everything: changing himself, saying the \\u201cright\\u201d things, becoming the version she might love.  But the more perfect he becomes, the more he loses himself.  TRY, AGAIN is a romantic sci-fi short film about dating, destiny, and the dangerous idea that love has to be earned by becoming someone else.  Because sometimes\\u2026 the only way to find love  is to stop trying.  A short film about modern relationships, self-worth, and emotional compatibility.\",\"poster_path\":\"\\/5FkZBPx2EDsfrUt850zXA20mVT8.jpg\",\"media_type\":\"movie\",\"original_language\":\"en\",\"genre_ids\":[14,10749,878,35],\"popularity\":1.0068,\"release_date\":\"2025-12-25\",\"softcore\":false,\"video\":true,\"vote_average\":0,\"vote_count\":0}', '2026-10-01 07:42:38', '2026-10-01 07:42:38'),
