(80, 37694, 'tv', 'My Big Fat Gypsy Wedding', '/yQrbMry3qna722fRGF9aQFSe6yL.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/ob5FyeZrRMmPa5caVme48IjjSt7.jpg\",\"id\":37694,\"name\":\"My Big Fat Gypsy Wedding\",\"original_name\":\"Big Fat Gypsy Weddings\",\"overview\":\"Big Fat Gypsy Weddings is a British documentary series broadcast on Channel 4, that explores the lives and traditions of several Irish Traveller families as they prepare to unite one of their number in marriage. The series also featured Romanichal in several episodes, and has been criticised for not accurately representing England\\u2019s Romani and Travelling community. It was first broadcast in February 2010 as a one-off documentary called My Big Fat Gypsy Wedding, filmed as part of the Cutting Edge series and voted Most Groundbreaking Show in the Cultural Diversity Awards 2010. A series of 5 episodes were later commissioned, and the series first aired in January 2011. A second series began airing in February 2012. A third series was not made, rather the show ended with six stand-alone specials.\",\"poster_path\":\"\\/yQrbMry3qna722fRGF9aQFSe6yL.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[99,10764],\"popularity\":2.6194,\"first_air_date\":\"2010-02-18\",\"softcore\":false,\"vote_average\":4.8,\"vote_count\":14,\"origin_country\":[\"GB\"]}', '2026-10-01 07:47:23', '2026-10-01 07:47:23'),
(81, 244723, 'movie', 'Gypsy Spirit - A Journey to the roots of Gypsy Music in India', '/q7b5bbnPy8aM89F30biANgEVa8K.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/vmDaFYQhCCbb34kKsJ5GawNEV0z.jpg\",\"id\":244723,\"title\":\"Gypsy Spirit - A Journey to the roots of Gypsy Music in India\",\"original_title\":\"Gypsy Spirit: Harri Stojka - Eine Reise\",\"overview\":\"\\\"I\'ve always played Gypsy Music, that\'s what my father taught me. But I would like to know where this music is from\\\". Willing to discover the roots of Gypsy Music, famous Austrian guitarist Harri Stojka goes on a journey to Rajasthan, India, to meet local musicians and play with them. There, he encounters several artists using the most original instruments, and always eager to share the joy of playing. More important, he realizes that the Gypsy spirit is something that brings them together. After all, they speak the same language: the language of music.\",\"poster_path\":\"\\/q7b5bbnPy8aM89F30biANgEVa8K.jpg\",\"media_type\":\"movie\",\"original_language\":\"en\",\"genre_ids\":[99,10402],\"popularity\":0.7629,\"release_date\":\"2010-09-03\",\"softcore\":false,\"video\":false,\"vote_average\":10,\"vote_count\":1}', '2026-10-01 07:47:23', '2026-10-01 07:47:23'),
