(92, 291076, 'tv', 'The Game', '/3Yz71kcHIUbvUN1eQOPanj9ABeG.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/4R1iyHONulL1qZNBtWuVu1B9TE9.jpg\",\"id\":291076,\"name\":\"The Game\",\"original_name\":\"The Game\",\"overview\":\"While haunted by memories of a failed arrest that allowed the Ripton Stalker to remain free, retired detective Inspector Huw Miller becomes suspicious of his enigmatic new neighbour Patrick Harbottle.\",\"poster_path\":\"\\/3Yz71kcHIUbvUN1eQOPanj9ABeG.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[18,80],\"popularity\":6.7912,\"first_air_date\":\"2025-05-12\",\"softcore\":false,\"vote_average\":6.5,\"vote_count\":13,\"origin_country\":[\"GB\"]}', '2026-10-01 07:47:36', '2026-10-01 07:47:36'),
(93, 211, 'tv', 'The Game', '/zmvRaCRcmi6lsriYxZmAR6uWHPS.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/lW3RCsfXXVGIBXyupMGT7dAYcze.jpg\",\"id\":211,\"name\":\"The Game\",\"original_name\":\"The Game\",\"overview\":\"When her boyfriend Derwin Davis is chosen as the new third-string wide receiver for the San Diego Sabers, Melanie Barnett decides to attend a local college so she can be with him. While Derwin worries about the plays on the field, Melanie adjusts to her new lifestyle. She gets a play-by-play account of the lives and relationships among NFL wives, girlfriends and mom\\/managers who use their best game to help their men stay on the field and on their arm.\",\"poster_path\":\"\\/zmvRaCRcmi6lsriYxZmAR6uWHPS.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[18,35],\"popularity\":24.7051,\"first_air_date\":\"2006-10-01\",\"softcore\":false,\"vote_average\":7.6,\"vote_count\":43,\"origin_country\":[\"US\"]}', '2026-10-01 07:47:36', '2026-10-01 07:47:36'),
(94, 67229, 'tv', 'Match Game', '/f4GmtNrtIzpqFNAxk3DFzk4zMmR.jpg', '{\"adult\":false,\"backdrop_path\":\"\\/14QakHe3Sxb6lTLDzRHzO2Zz826.jpg\",\"id\":67229,\"name\":\"Match Game\",\"original_name\":\"Match Game\",\"overview\":\"A modern reboot of the classic 70s game show that features two contestants attempting to match the answers of six celebrities in a game of fill-in-the-blank.\",\"poster_path\":\"\\/f4GmtNrtIzpqFNAxk3DFzk4zMmR.jpg\",\"media_type\":\"tv\",\"original_language\":\"en\",\"genre_ids\":[10764,35],\"popularity\":28.2833,\"first_air_date\":\"2016-06-26\",\"softcore\":false,\"vote_average\":6.5,\"vote_count\":27,\"origin_country\":[\"US\"]}', '2026-10-01 07:47:36', '2026-10-01 07:47:36');
